mapper.select:


    DELETED = 0

        AND ENTERPRISE_ID = #{enterpriseId}


        AND ENTERPRISE_NAME LIKE CONCAT('%', #{enterpriseName}, '%')


        AND REPORT_YEAR = #{reportYear}


        AND REPORT_PERIOD = #{reportPeriod}


        AND DATA_STATUS = #{dataStatus}


        AND REPORT_DATE >= #{startDate}


        AND REPORT_DATE <= #{endDate}


ORDER BY REPORT_YEAR DESC, REPORT_PERIOD DESC, CREATE_TIME DESC

WHERE ENTERPRISE_ID = #{enterpriseId} AND DELETED = 0 ORDER BY REPORT_YEAR DESC, REPORT_PERIOD DESC
LIMIT #{limit}
OFFSET 0 ROWS FETCH NEXT #{limit} ROWS ONLY
